// func multiDot4TripleBAVX512Generic16(out *[12]float32, a, b0, b1, b2 *float32, K int)
// 4 A x 3 B, K a positive multiple of 8 with K >= 32 (K%32 remainder is
// handled by full-width 16 and zero-padded 8 tails).  PP-OCR uses
// K=48/96/120/192/384/768 here.
// The AVX2 generic kernel is a dominant detector/recognizer hotspot on Zen4;
// this keeps all twelve output accumulators in ZMM registers and shares each
// 16-float A load across three B columns.
// Frame: out+0, a+8, b0+16, b1+24, b2+32, K+40
TEXT ·multiDot4TripleBAVX512Generic16(SB), NOSPLIT, $0-48
	MOVQ out+0(FP), R11
	MOVQ a+8(FP), SI
	MOVQ b0+16(FP), DI
	MOVQ b1+24(FP), R15
	MOVQ b2+32(FP), R14
	MOVQ K+40(FP), CX

	MOVQ CX, AX
	SHLQ $2, AX
	MOVQ SI, R8
	LEAQ (SI)(AX*1), R9
	LEAQ (R9)(AX*1), R10
	LEAQ (R10)(AX*1), R12

	VXORPS Z0, Z0, Z0
	VXORPS Z1, Z1, Z1
	VXORPS Z2, Z2, Z2
	VXORPS Z3, Z3, Z3
	VXORPS Z4, Z4, Z4
	VXORPS Z5, Z5, Z5
	VXORPS Z6, Z6, Z6
	VXORPS Z7, Z7, Z7
	VXORPS Z8, Z8, Z8
	VXORPS Z9, Z9, Z9
	VXORPS Z10, Z10, Z10
	VXORPS Z11, Z11, Z11

	// PP-OCR's selected widths are all multiples of 32.  Process two ZMM
	// chunks per trip to halve loop/AGU overhead while the twelve independent
	// FMA dependency chains hide the extra load latency.
	MOVQ CX, R13
	SHRQ $5, R13

tri4_generic16_loop:
	VMOVUPS (DI), Z13
	VMOVUPS (R15), Z14
	VMOVUPS (R14), Z15
	VMOVUPS (R8), Z12
	VFMADD231PS Z12, Z13, Z0
	VFMADD231PS Z12, Z14, Z4
	VFMADD231PS Z12, Z15, Z8
	VMOVUPS (R9), Z12
	VFMADD231PS Z12, Z13, Z1
	VFMADD231PS Z12, Z14, Z5
	VFMADD231PS Z12, Z15, Z9
	VMOVUPS (R10), Z12
