	VMOVUPS 64(R14), Z15
	VMOVUPS 64(R8), Z12
	VFMADD231PS Z12, Z13, Z0
	VFMADD231PS Z12, Z14, Z4
	VFMADD231PS Z12, Z15, Z8
	VMOVUPS 64(R9), Z12
	VFMADD231PS Z12, Z13, Z1
	VFMADD231PS Z12, Z14, Z5
	VFMADD231PS Z12, Z15, Z9
	VMOVUPS 64(R10), Z12
	VFMADD231PS Z12, Z13, Z2
	VFMADD231PS Z12, Z14, Z6
	VFMADD231PS Z12, Z15, Z10
	VMOVUPS 64(R12), Z12
	VFMADD231PS Z12, Z13, Z3
	VFMADD231PS Z12, Z14, Z7
	VFMADD231PS Z12, Z15, Z11
	ADDQ $128, DI
	ADDQ $128, R15
	ADDQ $128, R14
	ADDQ $128, R8
	ADDQ $128, R9
	ADDQ $128, R10
	ADDQ $128, R12
	DECQ R13
	JNZ tri4_generic16_loop

	// Tail: K%32 in {16, 24} (e.g. K=48 -> 16, K=120 -> 24). CX still holds
	// K. First a full-width 16-float chunk when bit 4 is set, then an
	// 8-float chunk zero-padded to 16 lanes when bit 3 is set. The padded
