	VFMADD231PS Z12, Z13, Z3
	VFMADD231PS Z12, Z14, Z7
	VFMADD231PS Z12, Z15, Z11
	ADDQ $64, DI
	ADDQ $64, R15
	ADDQ $64, R14
	ADDQ $64, R8
	ADDQ $64, R9
	ADDQ $64, R10
	ADDQ $64, R12
