// func multiDot4DualBAVX512Generic16(out *[8]float32, a, b0, b1 *float32, K int)
// 4 A x 2 B, K a positive multiple of 8 with K >= 32 (16/8-wide tails for
// the K%32 remainder).  The PP-OCR pointwise projections use 96/192/384,
// all divisible by 32.  Eight independent ZMM
// accumulators make this substantially cheaper than the AVX2 8-wide walk.
// Frame: out+0, a+8, b0+16, b1+24, K+32
TEXT ·multiDot4DualBAVX512Generic16(SB), NOSPLIT, $0-40
	MOVQ out+0(FP), R11
	MOVQ a+8(FP), SI
	MOVQ b0+16(FP), DI
	MOVQ b1+24(FP), R15
