	MOVQ CX, AX
	SHLQ $2, AX
	MOVQ SI, R8
	LEAQ (SI)(AX*1), R9
	LEAQ (R9)(AX*1), R10
	LEAQ (R10)(AX*1), R12

	VXORPS Z0, Z0, Z0
	VXORPS Z1, Z1, Z1
	VXORPS Z2, Z2, Z2
	VXORPS Z3, Z3, Z3
	VXORPS Z4, Z4, Z4
	VXORPS Z5, Z5, Z5
	VXORPS Z6, Z6, Z6
	VXORPS Z7, Z7, Z7

	MOVQ CX, R13
	SHRQ $5, R13
	TESTQ R13, R13
	JZ    dual4_tailStart // K < 32: empty main loop, tails consume everything

dual4_generic16_loop:
	VMOVUPS (DI), Z9
	VMOVUPS (R15), Z10
	VMOVUPS (R8), Z8
	VFMADD231PS Z8, Z9, Z0
	VFMADD231PS Z8, Z10, Z4
	VMOVUPS (R9), Z8
	VFMADD231PS Z8, Z9, Z1
