	VFMADD231PS Z8, Z10, Z6
	VMOVUPS (R12), Z8
	VFMADD231PS Z8, Z9, Z3
	VFMADD231PS Z8, Z10, Z7
	VMOVUPS 64(DI), Z9
	VMOVUPS 64(R15), Z10
	VMOVUPS 64(R8), Z8
	VFMADD231PS Z8, Z9, Z0
	VFMADD231PS Z8, Z10, Z4
	VMOVUPS 64(R9), Z8
	VFMADD231PS Z8, Z9, Z1
	VFMADD231PS Z8, Z10, Z5
	VMOVUPS 64(R10), Z8
	VFMADD231PS Z8, Z9, Z2
	VFMADD231PS Z8, Z10, Z6
	VMOVUPS 64(R12), Z8
	VFMADD231PS Z8, Z9, Z3
	VFMADD231PS Z8, Z10, Z7
	ADDQ $128, DI
	ADDQ $128, R15
	ADDQ $128, R8
	ADDQ $128, R9
	ADDQ $128, R10
	ADDQ $128, R12
	DECQ R13
	JNZ dual4_generic16_loop

	// Tail: K%32 in {16, 24} (K=48 -> 16, K=120 -> 24; K<32 enters here
	// directly via dual4_tailStart). CX still holds K.
	// See the triple kernel's tail comment for the zero-padding rationale.
dual4_tailStart:
	TESTQ $16, CX
	JZ dual4_noTail16
	VMOVUPS (DI), Z9
	VMOVUPS (R15), Z10
	VMOVUPS (R8), Z8
	VFMADD231PS Z8, Z9, Z0
	VFMADD231PS Z8, Z10, Z4
	VMOVUPS (R9), Z8
	VFMADD231PS Z8, Z9, Z1
	VFMADD231PS Z8, Z10, Z5
	VMOVUPS (R10), Z8
