	VFMADD231PS Z8, Z10, Z6
	VMOVUPS (R12), Z8
	VFMADD231PS Z8, Z9, Z3
	VFMADD231PS Z8, Z10, Z7
	ADDQ $64, DI
	ADDQ $64, R15
	ADDQ $64, R8
	ADDQ $64, R9
	ADDQ $64, R10
	ADDQ $64, R12
dual4_noTail16:
	TESTQ $8, CX
	JZ dual4_noTail8
	VXORPS Z11, Z11, Z11
	VMOVUPS (DI), Y9
	VINSERTF64X4 $0, Y9, Z11, Z9
	VMOVUPS (R15), Y10
