// func multiDot8TriplePlainAVX512K512N1536(out *float32, a, b0, b1, b2 *float32, m, n int, bn0, bn1, bn2 float32)
// Encoder fused: 8A×3B K=512 + bias into out[m:m+8, n:n+3], N=1536.
// Frame: out+0 a+8 b0+16 b1+24 b2+32 m+40 n+48 bn0+56 bn1+60 bn2+64 → 68
// Stack $8: out base address.
TEXT ·multiDot8TriplePlainAVX512K512N1536(SB), NOSPLIT, $8-68
	MOVQ out+0(FP), R11
	MOVQ m+40(FP), AX
	MOVQ n+48(FP), BX
	// base = (m*1536 + n) * 4
	LEAQ (AX)(AX*2), AX // m*3
	SHLQ $9, AX // m*1536
	ADDQ BX, AX
	SHLQ $2, AX
	ADDQ AX, R11
	MOVQ R11, 0(SP)

	MOVQ a+8(FP), SI
	MOVQ b0+16(FP), DI
	MOVQ b1+24(FP), R15
	MOVQ b2+32(FP), R14

	VXORPS Z0, Z0, Z0
	VXORPS Z1, Z1, Z1
