	VXORPS Z20, Z20, Z20
	VXORPS Z21, Z21, Z21
	VXORPS Z22, Z22, Z22
	VXORPS Z23, Z23, Z23

	// 32×16-float chunks / 2 = 16 iters; SI=&A0[k], R8=counter
	MOVQ $16, R8
