	ADDQ rowOff0+48(FP), DI
	MOVQ data+24(FP), R15
	ADDQ rowOff1+56(FP), R15
	// SI = &A0[0]; rows at r*8192(SI). Single base — one ADDQ per K step.

	VXORPS Z0, Z0, Z0
	VXORPS Z1, Z1, Z1
	VXORPS Z2, Z2, Z2
	VXORPS Z3, Z3, Z3
