// func q8DualMultiDot8AccumAVX512N64(out *float32, a *float32, data *byte, scales0, scales1 *float32, rowOff0, rowOff1 int, m, n int, bn0, bn1 float32)
// FFN down fused: 8A×2B one-pass + residual/bias store for N=512.
// out points to &out[0]; writes rows m..m+7, cols n,n+1.
// Frame: out+0 a+8 data+16 s0+24 s1+32 off0+40 off1+48 m+56 n+64 bn0+72 bn1+76 → 80
// Stack $16: save out base address (m*N+n).
TEXT ·q8DualMultiDot8AccumAVX512N64(SB), NOSPLIT, $16-80
	MOVQ out+0(FP), R11
	MOVQ m+56(FP), AX
	MOVQ n+64(FP), BX
	// base = (m*512 + n) * 4
	SHLQ $9, AX // m*512
	ADDQ BX, AX
	SHLQ $2, AX
	ADDQ AX, R11
	MOVQ R11, 0(SP)
	// Pull residual destination into cache before FMA (accum path).
	PREFETCHT0 (R11)
	PREFETCHT0 2048(R11)
	PREFETCHT0 4096(R11)
	PREFETCHT0 6144(R11)
	PREFETCHT0 8192(R11)
	PREFETCHT0 10240(R11)
	PREFETCHT0 12288(R11)
	PREFETCHT0 14336(R11)

	MOVQ a+8(FP), SI
	MOVQ data+16(FP), DI
	MOVQ scales0+24(FP), AX
	MOVQ scales1+32(FP), BX
	ADDQ rowOff0+40(FP), DI
	MOVQ data+16(FP), R15
	ADDQ rowOff1+48(FP), R15
	// SI = &A0[0]; rows at r*8192(SI).

	VXORPS Z0, Z0, Z0
	VXORPS Z1, Z1, Z1
	VXORPS Z2, Z2, Z2
	VXORPS Z3, Z3, Z3
	VXORPS Z4, Z4, Z4
	VXORPS Z5, Z5, Z5
	VXORPS Z6, Z6, Z6
	VXORPS Z7, Z7, Z7
	VXORPS Z8, Z8, Z8
	VXORPS Z9, Z9, Z9
	VXORPS Z10, Z10, Z10
	VXORPS Z11, Z11, Z11
	VXORPS Z12, Z12, Z12
	VXORPS Z13, Z13, Z13
	VXORPS Z14, Z14, Z14
	VXORPS Z15, Z15, Z15

	// 64 blocks / 2 per iter = 32 iters
	MOVQ $32, R11
q8d8acc_loop:
	PREFETCHT0 408(DI)
	PREFETCHT0 408(R15)
	PREFETCHT0 384(SI)
	PREFETCHT0 8576(SI)
	PREFETCHT0 16768(SI)
	PREFETCHT0 33152(SI)
	VBROADCASTSS (AX), Z30
