// func quantizePanel8Q8UAVX512(q *int8, s *float32, a *float32)
// 8×2048 non-neg A → u8 block-major packs + f32 scales (v6 dual-row ILP).
// q layout: block-major [64][8][32]; s: block-major [64][8].
// Frame: q+0 s+8 a+16 → 24
TEXT ·quantizePanel8Q8UAVX512(SB), NOSPLIT, $16-24
	MOVQ q+0(FP), DI
	MOVQ s+8(FP), R8
	MOVQ a+16(FP), SI
	MOVL $0x42fe0000, AX // 127.0f
	MOVL AX, 0(SP)
	VBROADCASTSS 0(SP), Z14
	MOVL $0x34000000, AX // ~1.2e-7f eps
	MOVL AX, 4(SP)
	VMOVSS 4(SP), X15
	MOVL $0x3c010204, AX // 1/127.0f
	MOVL AX, 8(SP)
	VMOVSS 8(SP), X13

	// 4 pairs of rows (0-1, 2-3, 4-5, 6-7)
	MOVQ $4, R9
	MOVQ $0, R14 // pair index 0..3 → row = pair*2
q8u_pair_loop:
	MOVQ $32, R10 // 64/2 blocks
	// R11=&A[r], R15=&A[r+1]; R12=&q[r*32]; R13=&s[r]
	MOVQ R14, AX
	SHLQ $1, AX // r = pair*2
	// a0 = SI + r*8192
	MOVQ AX, BX
	SHLQ $13, BX // r*8192
	LEAQ (SI)(BX*1), R11
	LEAQ 8192(R11), R15
	// q0 = DI + r*32
	MOVQ AX, BX
	SHLQ $5, BX // r*32
	LEAQ (DI)(BX*1), R12
	// s0 = R8 + r*4
	LEAQ (R8)(AX*4), R13
q8u_blk_loop:
	PREFETCHT0 256(R11)
	PREFETCHT0 256(R15)
	VMOVUPS (R11), Z0
	VMOVUPS 64(R11), Z1
	VMOVUPS (R15), Z8
	VMOVUPS 64(R15), Z9
	VMAXPS Z0, Z1, Z2
	VEXTRACTF32X8 $1, Z2, Y3
	VMAXPS Y2, Y3, Y2
	VEXTRACTF32X4 $1, Y2, X3
	VMAXPS X2, X3, X2
	VSHUFPD $1, X2, X2, X3
	VMAXPS X2, X3, X2
	VMOVSHDUP X2, X3
	VMAXSS X2, X3, X2
	VMAXPS Z8, Z9, Z10
	VEXTRACTF32X8 $1, Z10, Y11
	VMAXPS Y10, Y11, Y10
	VEXTRACTF32X4 $1, Y10, X11
