// func quantizePanel8Q8SK512AVX512(q *int8, s *float32, a *float32)
// 8×512 signed A → +128-biased u8 block-major packs + f32 scales (amax/127).
// q layout: block-major [16][8][32]; s: block-major [16][8].
// Frame: q+0 s+8 a+16 → 24
TEXT ·quantizePanel8Q8SK512AVX512(SB), NOSPLIT, $32-24
	MOVQ q+0(FP), DI
	MOVQ s+8(FP), R8
	MOVQ a+16(FP), SI
	MOVL $0x42fe0000, AX // 127.0f
	MOVL AX, 0(SP)
	VBROADCASTSS 0(SP), Z14
	MOVL $0x34000000, AX // ~1.2e-7f eps
	MOVL AX, 4(SP)
	VMOVSS 4(SP), X15
	MOVL $0x3c010204, AX // 1/127.0f
	MOVL AX, 8(SP)
	VMOVSS 8(SP), X13
	MOVL $0x7fffffff, AX // abs mask
	MOVL AX, 12(SP)
	VBROADCASTSS 12(SP), Z12
	MOVL $0x43000000, AX // 128.0f bias
	MOVL AX, 16(SP)
	VBROADCASTSS 16(SP), Z6

	MOVQ $4, R9
	MOVQ $0, R14 // pair index 0..3 → row = pair*2
q8s_pair_loop:
	MOVQ $8, R10 // 16/2 blocks
