// func quantizePanel8Q8SRowK512AVX512(q *int8, s *float32, a *float32)
// 8×512 signed A → +128-biased u8 packs, per-row scale (amax/127).
// q layout: block-major [16][8][32]; s: [8] per row.
// Frame: q+0 s+8 a+16 → 24
TEXT ·quantizePanel8Q8SRowK512AVX512(SB), NOSPLIT, $32-24
	MOVQ q+0(FP), DI
	MOVQ s+8(FP), R8
	MOVQ a+16(FP), SI
	MOVL $0x42fe0000, AX // 127.0f
	MOVL AX, 0(SP)
	VBROADCASTSS 0(SP), Z14
	MOVL $0x34000000, AX // ~1.2e-7f eps
	MOVL AX, 4(SP)
	VMOVSS 4(SP), X15
	MOVL $0x3c010204, AX // 1/127.0f
	MOVL AX, 8(SP)
	VMOVSS 8(SP), X13
	MOVL $0x7fffffff, AX // abs mask
	MOVL AX, 12(SP)
	VBROADCASTSS 12(SP), Z12
	MOVL $0x43000000, AX // 128.0f bias
	MOVL AX, 16(SP)
	VBROADCASTSS 16(SP), Z6

	MOVQ $8, R10 // rows
	MOVQ SI, R11 // A ptr (flows across rows)
	MOVQ DI, R15 // q row base = DI + r*32
	MOVQ R8, R13 // s ptr
q8sr_row_loop:
	// amax over the row's 512 floats: 8 batches of 4 ZMM, running max in Z4
	VMOVUPS 0(R11), Z0
	VMOVUPS 64(R11), Z1
	VMOVUPS 128(R11), Z2
	VMOVUPS 192(R11), Z3
	VANDPS Z12, Z0, Z0
	VANDPS Z12, Z1, Z1
	VANDPS Z12, Z2, Z2
	VANDPS Z12, Z3, Z3
	VMAXPS Z0, Z1, Z0
	VMAXPS Z2, Z3, Z2
	VMAXPS Z0, Z2, Z4
	VMOVUPS 256(R11), Z0
	VMOVUPS 320(R11), Z1
	VMOVUPS 384(R11), Z2
	VMOVUPS 448(R11), Z3
	VANDPS Z12, Z0, Z0
	VANDPS Z12, Z1, Z1
	VANDPS Z12, Z2, Z2
	VANDPS Z12, Z3, Z3
	VMAXPS Z0, Z1, Z0
	VMAXPS Z2, Z3, Z2
	VMAXPS Z2, Z0, Z0
	VMAXPS Z4, Z0, Z4
	VMOVUPS 512(R11), Z0
	VMOVUPS 576(R11), Z1
	VMOVUPS 640(R11), Z2
	VMOVUPS 704(R11), Z3
	VANDPS Z12, Z0, Z0
	VANDPS Z12, Z1, Z1
	VANDPS Z12, Z2, Z2
	VANDPS Z12, Z3, Z3
	VMAXPS Z0, Z1, Z0
	VMAXPS Z2, Z3, Z2
	VMAXPS Z2, Z0, Z0
	VMAXPS Z4, Z0, Z4
	VMOVUPS 768(R11), Z0
	VMOVUPS 832(R11), Z1
	VMOVUPS 896(R11), Z2
	VMOVUPS 960(R11), Z3
	VANDPS Z12, Z0, Z0
	VANDPS Z12, Z1, Z1
	VANDPS Z12, Z2, Z2
	VANDPS Z12, Z3, Z3
	VMAXPS Z0, Z1, Z0
	VMAXPS Z2, Z3, Z2
	VMAXPS Z2, Z0, Z0
	VMAXPS Z4, Z0, Z4
	VMOVUPS 1024(R11), Z0
	VMOVUPS 1088(R11), Z1
	VMOVUPS 1152(R11), Z2
	VMOVUPS 1216(R11), Z3
	VANDPS Z12, Z0, Z0
	VANDPS Z12, Z1, Z1
	VANDPS Z12, Z2, Z2
	VANDPS Z12, Z3, Z3
	VMAXPS Z0, Z1, Z0
	VMAXPS Z2, Z3, Z2
	VMAXPS Z2, Z0, Z0
	VMAXPS Z4, Z0, Z4
	VMOVUPS 1280(R11), Z0
	VMOVUPS 1344(R11), Z1
	VMOVUPS 1408(R11), Z2
	VMOVUPS 1472(R11), Z3
	VANDPS Z12, Z0, Z0
	VANDPS Z12, Z1, Z1
	VANDPS Z12, Z2, Z2
	VANDPS Z12, Z3, Z3
	VMAXPS Z0, Z1, Z0
	VMAXPS Z2, Z3, Z2
	VMAXPS Z2, Z0, Z0
	VMAXPS Z4, Z0, Z4
	VMOVUPS 1536(R11), Z0
	VMOVUPS 1600(R11), Z1
	VMOVUPS 1664(R11), Z2
	VMOVUPS 1728(R11), Z3
	VANDPS Z12, Z0, Z0
	VANDPS Z12, Z1, Z1
	VANDPS Z12, Z2, Z2
	VANDPS Z12, Z3, Z3
	VMAXPS Z0, Z1, Z0
	VMAXPS Z2, Z3, Z2
	VMAXPS Z2, Z0, Z0
	VMAXPS Z4, Z0, Z4
	VMOVUPS 1792(R11), Z0
	VMOVUPS 1856(R11), Z1
	VMOVUPS 1920(R11), Z2
	VMOVUPS 1984(R11), Z3
	VANDPS Z12, Z0, Z0
	VANDPS Z12, Z1, Z1
	VANDPS Z12, Z2, Z2
	VANDPS Z12, Z3, Z3
	VMAXPS Z0, Z1, Z0
	VMAXPS Z2, Z3, Z2
	VMAXPS Z2, Z0, Z0
	VMAXPS Z4, Z0, Z4
	VEXTRACTF32X8 $1, Z4, Y1
	VMAXPS Y4, Y1, Y4
	VEXTRACTF32X4 $1, Y4, X1
	VMAXPS X4, X1, X4
	VSHUFPD $1, X4, X4, X1
	VMAXPS X4, X1, X4
	VMOVSHDUP X4, X1
	VMAXSS X4, X1, X4 // amax
	VMOVAPS X4, X0
	VMULSS X13, X0, X4 // scale = amax/127
	VMAXSS X15, X0, X3
	VRCP14SS X3, X3, X3
	VMULSS X14, X3, X3 // inv = 127/amax
	VBROADCASTSS X3, Z5
	VMOVSS X4, (R13)
	MOVQ R15, R12 // q block ptr for this row
	MOVQ $16, R14
q8sr_blk_loop:
	VMOVUPS (R11), Z0
	VMOVUPS 64(R11), Z1
	VMULPS Z5, Z0, Z0
	VMULPS Z5, Z1, Z1
	VADDPS Z6, Z0, Z0
	VADDPS Z6, Z1, Z1
	VCVTPS2DQ Z0, Z0
	VCVTPS2DQ Z1, Z1
	VPMOVDB Z0, X4
	VPMOVDB Z1, X7
	VMOVUPS X4, (R12)
	VMOVUPS X7, 16(R12)
	ADDQ $128, R11
	ADDQ $256, R12
	DECQ R14
	JNZ  q8sr_blk_loop
	ADDQ $32, R15 // next row's q base
	ADDQ $4, R13 // next s
	DECQ R10
	JNZ  q8sr_row_loop
	VZEROUPPER
	RET

