// func quantizePanel4Q8SK512ZmmAVX512(q *int8, s *float32, sA *float32, a *float32)
// 4×512 signed A → +128-biased u8 packs [g][4][64] + block-major f32 scales
// + prearranged per-tick lane vecs sA[g*64 + r*16].
// Frame: q+0 s+8 sA+16 a+24 → 32
TEXT ·quantizePanel4Q8SK512ZmmAVX512(SB), NOSPLIT, $32-32
	MOVQ q+0(FP), DI
	MOVQ s+8(FP), R8
	MOVQ a+24(FP), SI
	MOVL $0x42fe0000, AX // 127.0f
	MOVL AX, 0(SP)
	VBROADCASTSS 0(SP), Z14
	MOVL $0x34000000, AX // ~1.2e-7f eps
	MOVL AX, 4(SP)
	VMOVSS 4(SP), X15
	MOVL $0x3c010204, AX // 1/127.0f
	MOVL AX, 8(SP)
	VMOVSS 8(SP), X13
	MOVL $0x7fffffff, AX // abs mask
	MOVL AX, 12(SP)
	VBROADCASTSS 12(SP), Z12
	MOVL $0x43000000, AX // 128.0f bias
	MOVL AX, 16(SP)
	VBROADCASTSS 16(SP), Z6

	MOVQ $2, R9
	MOVQ $0, R14 // pair index 0..1 → row = pair*2
q8s4_pair_loop:
	MOVQ $8, R10 // 8 groups
	MOVQ R14, AX
	SHLQ $1, AX // r = pair*2
	MOVQ AX, BX
	SHLQ $11, BX // r*2048
	LEAQ (SI)(BX*1), R11
	LEAQ 2048(R11), R15
	MOVQ AX, BX
	SHLQ $6, BX // r*64
	LEAQ (DI)(BX*1), R12
	LEAQ (R8)(AX*4), R13
q8s4_blk_loop:
	PREFETCHT0 256(R11)
	PREFETCHT0 256(R15)
	VMOVUPS (R11), Z0
	VMOVUPS 64(R11), Z1
	VMOVUPS (R15), Z8
	VMOVUPS 64(R15), Z9
	VANDPS Z12, Z0, Z2
	VANDPS Z12, Z1, Z3
	VANDPS Z12, Z8, Z10
	VANDPS Z12, Z9, Z11
	VMAXPS Z2, Z3, Z2
	VMAXPS Z10, Z11, Z10
	VEXTRACTF32X8 $1, Z2, Y3
	VMAXPS Y2, Y3, Y2
	VEXTRACTF32X4 $1, Y2, X3
	VMAXPS X2, X3, X2
	VSHUFPD $1, X2, X2, X3
	VMAXPS X2, X3, X2
	VMOVSHDUP X2, X3
	VMAXSS X2, X3, X2
	VEXTRACTF32X8 $1, Z10, Y11
	VMAXPS Y10, Y11, Y10
	VEXTRACTF32X4 $1, Y10, X11
	VMAXPS X10, X11, X10
	VSHUFPD $1, X10, X10, X11
	VMAXPS X10, X11, X10
	VMOVSHDUP X10, X11
	VMAXSS X10, X11, X10
	VMULSS X13, X2, X4
	VMAXSS X15, X2, X3
	VRCP14SS X3, X3, X3
	VMULSS X14, X3, X3
	VBROADCASTSS X3, Z5
	VMOVSS X4, (R13)
	VMULPS Z5, Z0, Z0
	VMULPS Z5, Z1, Z1
	VADDPS Z6, Z0, Z0
	VADDPS Z6, Z1, Z1
	VCVTPS2DQ Z0, Z0
	VCVTPS2DQ Z1, Z1
	VPMOVDB Z0, X4
	VPMOVDB Z1, X7
	VMOVUPS X4, (R12)
	VMOVUPS X7, 16(R12)
	VMULSS X13, X10, X4
	VMAXSS X15, X10, X3
	VRCP14SS X3, X3, X3
	VMULSS X14, X3, X3
	VBROADCASTSS X3, Z5
	VMOVSS X4, 4(R13)
	VMULPS Z5, Z8, Z8
	VMULPS Z5, Z9, Z9
	VADDPS Z6, Z8, Z8
	VADDPS Z6, Z9, Z9
	VCVTPS2DQ Z8, Z8
	VCVTPS2DQ Z9, Z9
	VPMOVDB Z8, X4
	VPMOVDB Z9, X7
	VMOVUPS X4, 64(R12)
	VMOVUPS X7, 80(R12)
	VMOVUPS 128(R11), Z0
	VMOVUPS 192(R11), Z1
	VMOVUPS 128(R15), Z8
	VMOVUPS 192(R15), Z9
	VANDPS Z12, Z0, Z2
	VANDPS Z12, Z1, Z3
	VANDPS Z12, Z8, Z10
	VANDPS Z12, Z9, Z11
	VMAXPS Z2, Z3, Z2
	VMAXPS Z10, Z11, Z10
	VEXTRACTF32X8 $1, Z2, Y3
	VMAXPS Y2, Y3, Y2
	VEXTRACTF32X4 $1, Y2, X3
	VMAXPS X2, X3, X2
	VSHUFPD $1, X2, X2, X3
	VMAXPS X2, X3, X2
	VMOVSHDUP X2, X3
	VMAXSS X2, X3, X2
	VEXTRACTF32X8 $1, Z10, Y11
	VMAXPS Y10, Y11, Y10
	VEXTRACTF32X4 $1, Y10, X11
	VMAXPS X10, X11, X10
	VSHUFPD $1, X10, X10, X11
	VMAXPS X10, X11, X10
	VMOVSHDUP X10, X11
	VMAXSS X10, X11, X10
	VMULSS X13, X2, X4
	VMAXSS X15, X2, X3
	VRCP14SS X3, X3, X3
	VMULSS X14, X3, X3
	VBROADCASTSS X3, Z5
	VMOVSS X4, 16(R13)
	VMULPS Z5, Z0, Z0
	VMULPS Z5, Z1, Z1
	VADDPS Z6, Z0, Z0
	VADDPS Z6, Z1, Z1
	VCVTPS2DQ Z0, Z0
	VCVTPS2DQ Z1, Z1
	VPMOVDB Z0, X4
	VPMOVDB Z1, X7
	VMOVUPS X4, 32(R12)
	VMOVUPS X7, 48(R12)
	VMULSS X13, X10, X4
	VMAXSS X15, X10, X3
	VRCP14SS X3, X3, X3
	VMULSS X14, X3, X3
	VBROADCASTSS X3, Z5
	VMOVSS X4, 20(R13)
	VMULPS Z5, Z8, Z8
	VMULPS Z5, Z9, Z9
	VADDPS Z6, Z8, Z8
	VADDPS Z6, Z9, Z9
	VCVTPS2DQ Z8, Z8
	VCVTPS2DQ Z9, Z9
	VPMOVDB Z8, X4
	VPMOVDB Z9, X7
	VMOVUPS X4, 96(R12)
	VMOVUPS X7, 112(R12)
	ADDQ $256, R11 // A: 64 floats
	ADDQ $256, R15
	ADDQ $256, R12 // q: 1 group tile (4 rows × 64B)
	ADDQ $32, R13 // s: 2 blocks × 4 floats (32B)
	DECQ R10
	JNZ  q8s4_blk_loop
	INCQ R14
	DECQ R9
	JNZ  q8s4_pair_loop

	// Prearrange per-tick sA lane vecs: sA[g*256 + r*64] = [s(2g,r)×8 | s(2g+1,r)×8].
	MOVQ sA+16(FP), R9
	MOVQ $0, R10 // g
q8s4_vec_g:
	MOVQ $0, R11 // r
q8s4_vec_r:
	MOVQ R10, AX
	SHLQ $3, AX // g*8 (4 rows per block)
	ADDQ R11, AX // g*8 + r  (s[(2g)*4 + r])
	VBROADCASTSS (R8)(AX*4), Y0
	VMOVUPS Y0, (R9)
	VBROADCASTSS 16(R8)(AX*4), Y0
	VMOVUPS Y0, 32(R9)
	ADDQ $64, R9
	INCQ R11
	CMPQ R11, $4
	JB   q8s4_vec_r
	INCQ R10
	CMPQ R10, $8
	JB   q8s4_vec_g
	VZEROUPPER
	RET

// func q8zDual4x4VNNIK512N512(out *float32, aQ *int8, aS *float32, qB *byte, sB0, sB1, sB2, sB3 *float32, off0, off1, off2, off3, m, n int, bn0, bn1, bn2, bn3 float32)
// Q8Z 4×4-tile ZMM per-block VNNI: A_u8(+128) × B_s8 stripped. N=512 K=512.
// Writes rows m..m+3, cols n..n+3. Bit-identical accum lanes to q8zDual8*.
// Frame: out+0 aQ+8 aS+16 qB+24 sB0+32 sB1+40 sB2+48 sB3+56 off0+64 off1+72 off2+80 off3+88 m+96 n+104 bn0+112 bn1+116 bn2+120 bn3+124 → 128
// Stack $8: 0(SP)=0x80 const. inline per-tick sB builds (AX-DX scale ptrs).
// Registers: Z0-15 accums (Z[c*4+r]), Z16-19 B, Z20-23 A, Z24-27 comp,
// Z28 0x80 const, Z29 temp, Z30 sA-vec, Z31 sB-vec.
TEXT ·q8zDual4x4VNNIK512N512(SB), NOSPLIT, $8-128
	MOVQ out+0(FP), R11
	MOVQ m+96(FP), AX
	MOVQ n+104(FP), BX
	SHLQ $9, AX // m*512
	ADDQ BX, AX
	SHLQ $2, AX
	ADDQ AX, R11

	MOVQ aQ+8(FP), SI
	MOVQ aS+16(FP), R8
	MOVQ qB+24(FP), R15
	MOVQ qB+24(FP), R14
	MOVQ qB+24(FP), R13
	MOVQ qB+24(FP), R12
	ADDQ off0+64(FP), R15
	ADDQ off1+72(FP), R14
	ADDQ off2+80(FP), R13
	ADDQ off3+88(FP), R12
	MOVQ sB0+32(FP), AX
	MOVQ sB1+40(FP), BX
	MOVQ sB2+48(FP), CX
	MOVQ sB3+56(FP), DX

	MOVL $0x80808080, R9
	MOVL R9, 0(SP)
	VPBROADCASTD 0(SP), Z28

	VXORPS Z0, Z0, Z0
	VXORPS Z1, Z1, Z1
	VXORPS Z2, Z2, Z2
	VXORPS Z3, Z3, Z3
	VXORPS Z4, Z4, Z4
	VXORPS Z5, Z5, Z5
	VXORPS Z6, Z6, Z6
	VXORPS Z7, Z7, Z7
	VXORPS Z8, Z8, Z8
	VXORPS Z9, Z9, Z9
