	VSHUFPD $1, X2, X2, X3
	VMAXPS X2, X3, X2
	VMOVSHDUP X2, X3
	VMAXSS X2, X3, X2
	VMAXPS Z8, Z9, Z10
	VEXTRACTF32X8 $1, Z10, Y11
	VMAXPS Y10, Y11, Y10
	VEXTRACTF32X4 $1, Y10, X11
	VMAXPS X10, X11, X10
	VSHUFPD $1, X10, X10, X11
	VMAXPS X10, X11, X10
	VMOVSHDUP X10, X11
	VMAXSS X10, X11, X10
	VMULSS X13, X2, X4
	VMAXSS X15, X2, X3
	VRCP14SS X3, X3, X3
	VMULSS X14, X3, X3
	VBROADCASTSS X3, Z5
	VMOVSS X4, (R13)
	VMULPS Z5, Z0, Z0
	VMULPS Z5, Z1, Z1
