	VCVTPS2DQ Z1, Z1
	VPMOVDB Z0, X6
	VPMOVDB Z1, X7
	VMOVUPS X6, (R12)
	VMOVUPS X7, 16(R12)
	VMULSS X13, X10, X4
	VMAXSS X15, X10, X3
	VRCP14SS X3, X3, X3
	VMULSS X14, X3, X3
	VBROADCASTSS X3, Z5
	VMOVSS X4, 4(R13)
	VMULPS Z5, Z8, Z8
	VMULPS Z5, Z9, Z9
	VCVTPS2DQ Z8, Z8
	VCVTPS2DQ Z9, Z9
	VPMOVDB Z8, X6
	VPMOVDB Z9, X7
	VMOVUPS X6, 64(R12)
	VMOVUPS X7, 80(R12)
	VMOVUPS 128(R11), Z0
	VMOVUPS 192(R11), Z1
	VMOVUPS 128(R15), Z8
	VMOVUPS 192(R15), Z9
	VMAXPS Z0, Z1, Z2
	VEXTRACTF32X8 $1, Z2, Y3
	VMAXPS Y2, Y3, Y2
