	VMAXSS X15, X2, X3
	VRCP14SS X3, X3, X3
	VMULSS X14, X3, X3
	VBROADCASTSS X3, Z5
	VMOVSS X4, 32(R13)
	VMULPS Z5, Z0, Z0
	VMULPS Z5, Z1, Z1
	VCVTPS2DQ Z0, Z0
	VCVTPS2DQ Z1, Z1
	VPMOVDB Z0, X6
	VPMOVDB Z1, X7
	VMOVUPS X6, 32(R12)
	VMOVUPS X7, 48(R12)
	VMULSS X13, X10, X4
	VMAXSS X15, X10, X3
	VRCP14SS X3, X3, X3
	VMULSS X14, X3, X3
	VBROADCASTSS X3, Z5
	VMOVSS X4, 36(R13)
	VMULPS Z5, Z8, Z8
	VMULPS Z5, Z9, Z9
	VCVTPS2DQ Z8, Z8
	VCVTPS2DQ Z9, Z9
	VPMOVDB Z8, X6
	VPMOVDB Z9, X7
	VMOVUPS X6, 96(R12)
	VMOVUPS X7, 112(R12)
	ADDQ $256, R11 // A: 64 floats
	ADDQ $256, R15
	ADDQ $512, R12 // q: 1 group tile (8 rows × 64B)
	ADDQ $64, R13 // s: 2 blocks × 8 floats
	DECQ R10
	JNZ  q8uz_blk_loop
	INCQ R14
	DECQ R9
	JNZ  q8uz_pair_loop
	VZEROUPPER
	RET

