// func multiDot8DualPlainAVX512K512N512(out *float32, a, b0, b1 *float32, m, n int, bn0, bn1 float32)
// Encoder dual remainder: 8A×2B K=512 + bias, N=512.
// Frame: out+0 a+8 b0+16 b1+24 m+32 n+40 bn0+48 bn1+52 → 56
// Stack $8: out base.
TEXT ·multiDot8DualPlainAVX512K512N512(SB), NOSPLIT, $8-56
	MOVQ out+0(FP), R11
	MOVQ m+32(FP), AX
	MOVQ n+40(FP), BX
	SHLQ $9, AX // m*512
	ADDQ BX, AX
	SHLQ $2, AX
	ADDQ AX, R11
	MOVQ R11, 0(SP)

	MOVQ a+8(FP), SI
	MOVQ b0+16(FP), DI
	MOVQ b1+24(FP), R15
	VXORPS Z0, Z0, Z0
	VXORPS Z1, Z1, Z1
	VXORPS Z2, Z2, Z2
