	VMOVUPS 64(R12), Z5
	VFMADD231PS Z5, Z4, Z3
	MOVSS 4(R13), X15
	VBROADCASTSS X15, Z15
	VPMOVSXBD 36(DI), Z4
	VCVTDQ2PS Z4, Z4
	VMULPS Z15, Z4, Z4
	VMOVUPS 128(R8), Z5
	VFMADD231PS Z5, Z4, Z0
	VMOVUPS 128(R9), Z5
	VFMADD231PS Z5, Z4, Z1
	VMOVUPS 128(R10), Z5
	VFMADD231PS Z5, Z4, Z2
	VMOVUPS 128(R12), Z5
	VFMADD231PS Z5, Z4, Z3
	VPMOVSXBD 52(DI), Z4
	VCVTDQ2PS Z4, Z4
	VMULPS Z15, Z4, Z4
	VMOVUPS 192(R8), Z5
	VFMADD231PS Z5, Z4, Z0
	VMOVUPS 192(R9), Z5
	VFMADD231PS Z5, Z4, Z1
	VMOVUPS 192(R10), Z5
	VFMADD231PS Z5, Z4, Z2
	VMOVUPS 192(R12), Z5
	VFMADD231PS Z5, Z4, Z3
	ADDQ $68, DI
	ADDQ $8, R13
	ADDQ $256, R8
	ADDQ $256, R9
	ADDQ $256, R10
	ADDQ $256, R12
	DECQ CX
	JNZ  qn64_loop

	VEXTRACTF32X8 $1, Z0, Y28
	VADDPS Y0, Y28, Y28
	VEXTRACTF32X4 $1, Y28, X29
	VADDPS X28, X29, X28
	VSHUFPD $1, X28, X28, X29
	VADDPS X28, X29, X28
	VMOVSHDUP X28, X29
	VADDSS X28, X29, X28
	VMOVSS X28, 0(R11)
	VEXTRACTF32X8 $1, Z1, Y28
	VADDPS Y1, Y28, Y28
	VEXTRACTF32X4 $1, Y28, X29
	VADDPS X28, X29, X28
	VSHUFPD $1, X28, X28, X29
	VADDPS X28, X29, X28
	VMOVSHDUP X28, X29
	VADDSS X28, X29, X28
	VMOVSS X28, 4(R11)
	VEXTRACTF32X8 $1, Z2, Y28
	VADDPS Y2, Y28, Y28
	VEXTRACTF32X4 $1, Y28, X29
	VADDPS X28, X29, X28
	VSHUFPD $1, X28, X28, X29
	VADDPS X28, X29, X28
	VMOVSHDUP X28, X29
	VADDSS X28, X29, X28
	VMOVSS X28, 8(R11)
	VEXTRACTF32X8 $1, Z3, Y28
	VADDPS Y3, Y28, Y28
	VEXTRACTF32X4 $1, Y28, X29
	VADDPS X28, X29, X28
	VSHUFPD $1, X28, X28, X29
	VADDPS X28, X29, X28
	VMOVSHDUP X28, X29
	VADDSS X28, X29, X28
	VMOVSS X28, 12(R11)
	VZEROUPPER
	RET

// func dequantRowScaledAVX512(dst []float32, data []byte, scales *float32, rowOff, nBlocks int)
// Single-row Q8→f32 with f32 scale cache. Frame matches AVX2 (72 bytes).
TEXT ·dequantRowScaledAVX512(SB), NOSPLIT, $0-72
	MOVQ dst+0(FP), SI
	MOVQ data+24(FP), DI
	MOVQ scales+48(FP), R8
	ADDQ rowOff+56(FP), DI
	MOVQ nBlocks+64(FP), CX
	TESTQ CX, CX
	JZ   dqs1_512_done

	MOVQ CX, R10
	SHRQ $1, R10
	TESTQ R10, R10
	JZ   dqs1_512_one

dqs1_512_loop2:
	PREFETCHT0 136(DI)
	PREFETCHT0 256(SI)
	VBROADCASTSS (R8), Z1
	VPMOVSXBD 2(DI), Z2
	VPMOVSXBD 18(DI), Z3
	VCVTDQ2PS Z2, Z2
	VCVTDQ2PS Z3, Z3
	VMULPS Z1, Z2, Z2
	VMULPS Z1, Z3, Z3
	VMOVUPS Z2, 0(SI)
	VMOVUPS Z3, 64(SI)
	VBROADCASTSS 4(R8), Z1
	VPMOVSXBD 36(DI), Z2
	VPMOVSXBD 52(DI), Z3
	VCVTDQ2PS Z2, Z2
	VCVTDQ2PS Z3, Z3
	VMULPS Z1, Z2, Z2
	VMULPS Z1, Z3, Z3
	VMOVUPS Z2, 128(SI)
	VMOVUPS Z3, 192(SI)
	ADDQ $68, DI
	ADDQ $8, R8
	ADDQ $256, SI
	DECQ R10
	JNZ  dqs1_512_loop2

	MOVQ nBlocks+64(FP), CX
	ANDQ $1, CX
	JZ   dqs1_512_done

dqs1_512_one:
	TESTQ CX, CX
	JZ   dqs1_512_done
dqs1_512_one_loop:
	VBROADCASTSS (R8), Z1
	VPMOVSXBD 2(DI), Z2
	VPMOVSXBD 18(DI), Z3
	VCVTDQ2PS Z2, Z2
	VCVTDQ2PS Z3, Z3
	VMULPS Z1, Z2, Z2
	VMULPS Z1, Z3, Z3
	VMOVUPS Z2, 0(SI)
	VMOVUPS Z3, 64(SI)
	ADDQ $34, DI
	ADDQ $4, R8
	ADDQ $128, SI
	DECQ CX
	JNZ  dqs1_512_one_loop

dqs1_512_done:
	VZEROUPPER
	RET

// func dequantRowScaledDualAVX512(dst0, dst1 []float32, data []byte, scales0, scales1 *float32, rowOff0, rowOff1, nBlocks int)
// Frame identical to dequantRowScaledDualAVX2 (112 bytes).
TEXT ·dequantRowScaledDualAVX512(SB), NOSPLIT, $0-112
	MOVQ dst0+0(FP), SI
	MOVQ dst1+24(FP), R10
	MOVQ data+48(FP), DI
	MOVQ scales0+72(FP), R8
	MOVQ scales1+80(FP), R9
	ADDQ rowOff0+88(FP), DI
	MOVQ data+48(FP), R15
	ADDQ rowOff1+96(FP), R15
	MOVQ nBlocks+104(FP), CX
	TESTQ CX, CX
	JZ   dqs512_done

	// dual-block when even
	MOVQ CX, R11
	SHRQ $1, R11
	TESTQ R11, R11
	JZ   dqs512_one

dqs512_loop2:
	PREFETCHT0 204(DI)
	PREFETCHT0 204(R15)
	PREFETCHT0 256(SI)
	PREFETCHT0 256(R10)
	VBROADCASTSS (R8), Z1
	VBROADCASTSS (R9), Z4
	VPMOVSXBD 2(DI), Z2
	VPMOVSXBD 2(R15), Z3
	VPMOVSXBD 18(DI), Z5
	VPMOVSXBD 18(R15), Z6
	VCVTDQ2PS Z2, Z2
	VCVTDQ2PS Z3, Z3
	VCVTDQ2PS Z5, Z5
	VCVTDQ2PS Z6, Z6
	VMULPS Z1, Z2, Z2
	VMULPS Z4, Z3, Z3
	VMULPS Z1, Z5, Z5
	VMULPS Z4, Z6, Z6
	VMOVUPS Z2, 0(SI)
	VMOVUPS Z3, 0(R10)
	VMOVUPS Z5, 64(SI)
	VMOVUPS Z6, 64(R10)
	VBROADCASTSS 4(R8), Z1
	VBROADCASTSS 4(R9), Z4
	VPMOVSXBD 36(DI), Z2
	VPMOVSXBD 36(R15), Z3
	VPMOVSXBD 52(DI), Z5
	VPMOVSXBD 52(R15), Z6
	VCVTDQ2PS Z2, Z2
	VCVTDQ2PS Z3, Z3
	VCVTDQ2PS Z5, Z5
	VCVTDQ2PS Z6, Z6
	VMULPS Z1, Z2, Z2
	VMULPS Z4, Z3, Z3
	VMULPS Z1, Z5, Z5
	VMULPS Z4, Z6, Z6
	VMOVUPS Z2, 128(SI)
	VMOVUPS Z3, 128(R10)
	VMOVUPS Z5, 192(SI)
	VMOVUPS Z6, 192(R10)
	ADDQ $68, DI
	ADDQ $68, R15
	ADDQ $8, R8
	ADDQ $8, R9
	ADDQ $256, SI
	ADDQ $256, R10
	DECQ R11
	JNZ  dqs512_loop2

	MOVQ nBlocks+104(FP), CX
	ANDQ $1, CX
	JZ   dqs512_done

dqs512_one:
	TESTQ CX, CX
	JZ   dqs512_done
dqs512_one_loop:
	VBROADCASTSS (R8), Z1
	VBROADCASTSS (R9), Z4
	VPMOVSXBD 2(DI), Z2
	VPMOVSXBD 2(R15), Z3
	VPMOVSXBD 18(DI), Z5
	VPMOVSXBD 18(R15), Z6
	VCVTDQ2PS Z2, Z2
	VCVTDQ2PS Z3, Z3
	VCVTDQ2PS Z5, Z5
	VCVTDQ2PS Z6, Z6
	VMULPS Z1, Z2, Z2
	VMULPS Z4, Z3, Z3
	VMULPS Z1, Z5, Z5
	VMULPS Z4, Z6, Z6
	VMOVUPS Z2, 0(SI)
	VMOVUPS Z3, 0(R10)
	VMOVUPS Z5, 64(SI)
	VMOVUPS Z6, 64(R10)
	ADDQ $34, DI
	ADDQ $34, R15
	ADDQ $4, R8
	ADDQ $4, R9
	ADDQ $128, SI
	ADDQ $128, R10
	DECQ CX
	JNZ  dqs512_one_loop

dqs512_done:
	VZEROUPPER
	RET

// func dequantRowScaledTripleAVX512(dst0, dst1, dst2 []float32, data []byte, scales0, scales1, scales2 *float32, rowOff0, rowOff1, rowOff2, nBlocks int)
// Three Q8 rows → float panels (triple multiDot feed). Frame 152 bytes.
// 4-block main (K=512 → 4 iters). 8-block body measured L1I thrash (share ↑).
// load-all-halves-then-cvt measured slower than half0-store||half1-expand.
TEXT ·dequantRowScaledTripleAVX512(SB), NOSPLIT, $0-152
	MOVQ dst0+0(FP), SI
	MOVQ dst1+24(FP), R10
	MOVQ dst2+48(FP), R12
	MOVQ data+72(FP), DI
	MOVQ scales0+96(FP), R8
	MOVQ scales1+104(FP), R9
	MOVQ scales2+112(FP), R11
	ADDQ rowOff0+120(FP), DI
	MOVQ data+72(FP), R15
	ADDQ rowOff1+128(FP), R15
	MOVQ data+72(FP), R13
	ADDQ rowOff2+136(FP), R13
	MOVQ nBlocks+144(FP), CX
	TESTQ CX, CX
	JZ   dqt512_done

	// 4-block main loop (K=512 → 16 blocks → 4 iters)
	MOVQ CX, BX
	SHRQ $2, BX
	TESTQ BX, BX
	JZ   dqt512_rem2

dqt512_loop4:
	PREFETCHT0 272(DI)
	PREFETCHT0 272(R15)
	PREFETCHT0 272(R13)
	// dst panel write stream (multiDot reads soon; T0 keeps L1 warm for stores)
	PREFETCHT0 512(SI)
	PREFETCHT0 512(R10)
	PREFETCHT0 512(R12)
	VBROADCASTSS (R8), Z1
	VBROADCASTSS (R9), Z4
	VBROADCASTSS (R11), Z7
	VPMOVSXBD 2(DI), Z2
	VPMOVSXBD 2(R15), Z3
	VPMOVSXBD 2(R13), Z5
	VCVTDQ2PS Z2, Z2
	VCVTDQ2PS Z3, Z3
	VCVTDQ2PS Z5, Z5
	VMULPS Z1, Z2, Z2
	VMULPS Z4, Z3, Z3
	VMULPS Z7, Z5, Z5
	VPMOVSXBD 18(DI), Z8
	VPMOVSXBD 18(R15), Z9
	VPMOVSXBD 18(R13), Z10
	VMOVUPS Z2, 0(SI)
	VMOVUPS Z3, 0(R10)
	VMOVUPS Z5, 0(R12)
	VCVTDQ2PS Z8, Z8
	VCVTDQ2PS Z9, Z9
	VCVTDQ2PS Z10, Z10
	VMULPS Z1, Z8, Z8
	VMULPS Z4, Z9, Z9
	VMULPS Z7, Z10, Z10
	VMOVUPS Z8, 64(SI)
	VMOVUPS Z9, 64(R10)
	VMOVUPS Z10, 64(R12)
	VBROADCASTSS 4(R8), Z1
	VBROADCASTSS 4(R9), Z4
	VBROADCASTSS 4(R11), Z7
	VPMOVSXBD 36(DI), Z2
	VPMOVSXBD 36(R15), Z3
	VPMOVSXBD 36(R13), Z5
	VCVTDQ2PS Z2, Z2
	VCVTDQ2PS Z3, Z3
	VCVTDQ2PS Z5, Z5
	VMULPS Z1, Z2, Z2
	VMULPS Z4, Z3, Z3
	VMULPS Z7, Z5, Z5
	VPMOVSXBD 52(DI), Z8
	VPMOVSXBD 52(R15), Z9
	VPMOVSXBD 52(R13), Z10
	VMOVUPS Z2, 128(SI)
	VMOVUPS Z3, 128(R10)
	VMOVUPS Z5, 128(R12)
	VCVTDQ2PS Z8, Z8
	VCVTDQ2PS Z9, Z9
	VCVTDQ2PS Z10, Z10
	VMULPS Z1, Z8, Z8
	VMULPS Z4, Z9, Z9
	VMULPS Z7, Z10, Z10
	VMOVUPS Z8, 192(SI)
	VMOVUPS Z9, 192(R10)
	VMOVUPS Z10, 192(R12)
	VBROADCASTSS 8(R8), Z1
	VBROADCASTSS 8(R9), Z4
	VBROADCASTSS 8(R11), Z7
	VPMOVSXBD 70(DI), Z2
	VPMOVSXBD 70(R15), Z3
	VPMOVSXBD 70(R13), Z5
	VCVTDQ2PS Z2, Z2
	VCVTDQ2PS Z3, Z3
	VCVTDQ2PS Z5, Z5
	VMULPS Z1, Z2, Z2
	VMULPS Z4, Z3, Z3
	VMULPS Z7, Z5, Z5
	VPMOVSXBD 86(DI), Z8
	VPMOVSXBD 86(R15), Z9
	VPMOVSXBD 86(R13), Z10
	VMOVUPS Z2, 256(SI)
	VMOVUPS Z3, 256(R10)
	VMOVUPS Z5, 256(R12)
	VCVTDQ2PS Z8, Z8
	VCVTDQ2PS Z9, Z9
	VCVTDQ2PS Z10, Z10
	VMULPS Z1, Z8, Z8
	VMULPS Z4, Z9, Z9
	VMULPS Z7, Z10, Z10
	VMOVUPS Z8, 320(SI)
	VMOVUPS Z9, 320(R10)
	VMOVUPS Z10, 320(R12)
	VBROADCASTSS 12(R8), Z1
	VBROADCASTSS 12(R9), Z4
	VBROADCASTSS 12(R11), Z7
	VPMOVSXBD 104(DI), Z2
	VPMOVSXBD 104(R15), Z3
	VPMOVSXBD 104(R13), Z5
	VCVTDQ2PS Z2, Z2
	VCVTDQ2PS Z3, Z3
	VCVTDQ2PS Z5, Z5
	VMULPS Z1, Z2, Z2
	VMULPS Z4, Z3, Z3
	VMULPS Z7, Z5, Z5
	VPMOVSXBD 120(DI), Z8
	VPMOVSXBD 120(R15), Z9
	VPMOVSXBD 120(R13), Z10
	VMOVUPS Z2, 384(SI)
	VMOVUPS Z3, 384(R10)
	VMOVUPS Z5, 384(R12)
	VCVTDQ2PS Z8, Z8
	VCVTDQ2PS Z9, Z9
	VCVTDQ2PS Z10, Z10
	VMULPS Z1, Z8, Z8
	VMULPS Z4, Z9, Z9
	VMULPS Z7, Z10, Z10
	VMOVUPS Z8, 448(SI)
	VMOVUPS Z9, 448(R10)
	VMOVUPS Z10, 448(R12)
	ADDQ $136, DI
	ADDQ $136, R15
	ADDQ $136, R13
	ADDQ $16, R8
	ADDQ $16, R9
	ADDQ $16, R11
	ADDQ $512, SI
	ADDQ $512, R10
	ADDQ $512, R12
	DECQ BX
	JNZ  dqt512_loop4

dqt512_rem2:
	MOVQ nBlocks+144(FP), CX
	ANDQ $3, CX
	JZ   dqt512_done
	// remaining 1–3 blocks
dqt512_one_loop:
	VBROADCASTSS (R8), Z1
	VBROADCASTSS (R9), Z4
	VBROADCASTSS (R11), Z7
	VPMOVSXBD 2(DI), Z2
	VPMOVSXBD 2(R15), Z3
	VPMOVSXBD 2(R13), Z5
	VCVTDQ2PS Z2, Z2
	VCVTDQ2PS Z3, Z3
	VCVTDQ2PS Z5, Z5
	VMULPS Z1, Z2, Z2
	VMULPS Z4, Z3, Z3
	VMULPS Z7, Z5, Z5
	VPMOVSXBD 18(DI), Z8
	VPMOVSXBD 18(R15), Z9
	VPMOVSXBD 18(R13), Z10
	VMOVUPS Z2, 0(SI)
	VMOVUPS Z3, 0(R10)
	VMOVUPS Z5, 0(R12)
	VCVTDQ2PS Z8, Z8
	VCVTDQ2PS Z9, Z9
	VCVTDQ2PS Z10, Z10
	VMULPS Z1, Z8, Z8
	VMULPS Z4, Z9, Z9
	VMULPS Z7, Z10, Z10
	VMOVUPS Z8, 64(SI)
	VMOVUPS Z9, 64(R10)
	VMOVUPS Z10, 64(R12)
	ADDQ $34, DI
	ADDQ $34, R15
	ADDQ $34, R13
	ADDQ $4, R8
	ADDQ $4, R9
	ADDQ $4, R11
	ADDQ $128, SI
	ADDQ $128, R10
	ADDQ $128, R12
	DECQ CX
	JNZ  dqt512_one_loop

dqt512_done:
	VZEROUPPER
	RET

// func dotQ8RowScaledAVX512(a *float32, data *byte, scales *float32, rowOff, nBlocks int) float32
// Single-row Q8 scaled dot, 16-wide (SenseVoice M remainder / M=1).
// Frame: a+0 data+8 scales+16 rowOff+24 nBlocks+32 ret+40 → 48
TEXT ·dotQ8RowScaledAVX512(SB), NOSPLIT, $0-44
	MOVQ a+0(FP), SI
	MOVQ data+8(FP), DI
	MOVQ scales+16(FP), R8
	ADDQ rowOff+24(FP), DI
	MOVQ nBlocks+32(FP), CX
	VXORPS Z0, Z0, Z0
	TESTQ CX, CX
	JZ   dqs512_dot_done

dqs512_dot_loop:
	PREFETCHT0 68(DI)
	PREFETCHT0 256(SI)
	VBROADCASTSS (R8), Z1
	ADDQ $4, R8
	// half0: bytes 2..17 → 16 floats
	VPMOVSXBD 2(DI), Z2
	VCVTDQ2PS Z2, Z2
	VMULPS Z1, Z2, Z2
	VMOVUPS (SI), Z3
	VFMADD231PS Z3, Z2, Z0
	// half1: bytes 18..33
	VPMOVSXBD 18(DI), Z2
	VCVTDQ2PS Z2, Z2
	VMULPS Z1, Z2, Z2
	VMOVUPS 64(SI), Z3
	VFMADD231PS Z3, Z2, Z0
	ADDQ $34, DI
	ADDQ $128, SI
	DECQ CX
	JNZ  dqs512_dot_loop

dqs512_dot_done:
	VEXTRACTF32X8 $1, Z0, Y1
	VADDPS Y0, Y1, Y0
	VEXTRACTF32X4 $1, Y0, X1
	VADDPS X0, X1, X0
	VSHUFPD $1, X0, X0, X1
	VADDPS X0, X1, X0
	VMOVSHDUP X0, X1
	VADDSS X0, X1, X0
	MOVSS X0, ret+40(FP)
	VZEROUPPER
	RET

// func q8DualDot2ScaledAVX512(out *[2]float32, a *float32, data *byte, scales0, scales1 *float32, rowOff0, rowOff1, nBlocks int)
// Dual-B Q8 scaled dots sharing A stream (M remainder / M=1 dual).
// Frame: out+0 a+8 data+16 s0+24 s1+32 off0+40 off1+48 nBlocks+56 → 64
TEXT ·q8DualDot2ScaledAVX512(SB), NOSPLIT, $0-64
	MOVQ out+0(FP), R11
	MOVQ a+8(FP), SI
	MOVQ data+16(FP), DI
	MOVQ scales0+24(FP), R8
	MOVQ scales1+32(FP), R9
	MOVQ nBlocks+56(FP), CX
	ADDQ rowOff0+40(FP), DI
	MOVQ data+16(FP), R15
	ADDQ rowOff1+48(FP), R15
	VXORPS Z0, Z0, Z0
	VXORPS Z1, Z1, Z1
	TESTQ CX, CX
	JZ   ddsc512_hsum

ddsc512_loop:
	PREFETCHT0 68(DI)
	PREFETCHT0 68(R15)
	PREFETCHT0 256(SI)
	VBROADCASTSS (R8), Z30
	VBROADCASTSS (R9), Z31
	ADDQ $4, R8
	ADDQ $4, R9
	// half0
	VPMOVSXBD 2(DI), Z2
	VPMOVSXBD 2(R15), Z3
	VCVTDQ2PS Z2, Z2
	VCVTDQ2PS Z3, Z3
	VMULPS Z30, Z2, Z2
	VMULPS Z31, Z3, Z3
	VMOVUPS (SI), Z4
	VFMADD231PS Z4, Z2, Z0
	VFMADD231PS Z4, Z3, Z1
	// half1
	VPMOVSXBD 18(DI), Z2
	VPMOVSXBD 18(R15), Z3
	VCVTDQ2PS Z2, Z2
	VCVTDQ2PS Z3, Z3
	VMULPS Z30, Z2, Z2
	VMULPS Z31, Z3, Z3
	VMOVUPS 64(SI), Z4
	VFMADD231PS Z4, Z2, Z0
	VFMADD231PS Z4, Z3, Z1
	ADDQ $34, DI
	ADDQ $34, R15
	ADDQ $128, SI
	DECQ CX
	JNZ  ddsc512_loop

ddsc512_hsum:
	VEXTRACTF32X8 $1, Z0, Y2
	VADDPS Y0, Y2, Y0
	VEXTRACTF32X4 $1, Y0, X2
	VADDPS X0, X2, X0
	VSHUFPD $1, X0, X0, X2
	VADDPS X0, X2, X0
	VMOVSHDUP X0, X2
	VADDSS X0, X2, X0
	MOVSS X0, (R11)

	VEXTRACTF32X8 $1, Z1, Y2
	VADDPS Y1, Y2, Y1
	VEXTRACTF32X4 $1, Y1, X2
	VADDPS X1, X2, X1
	VSHUFPD $1, X1, X1, X2
	VADDPS X1, X2, X1
	VMOVSHDUP X1, X2
	VADDSS X1, X2, X1
	MOVSS X1, 4(R11)

	VZEROUPPER
	RET

// func wsumBatched8Add128DualAVX512(o0,o1,o2,o3,o4,o5,o6,o7, va, vb, wa, wb *float32)
// out_t += wa[t]*va + wb[t]*vb, dim=128, 16-wide.
// Frame: o0+0..o7+56 va+64 vb+72 wa+80 wb+88 → 96
TEXT ·wsumBatched8Add128DualAVX512(SB), NOSPLIT, $0-96
	MOVQ o0+0(FP), R8
	MOVQ o1+8(FP), R9
	MOVQ o2+16(FP), R10
	MOVQ o3+24(FP), R11
	MOVQ o4+32(FP), R12
	MOVQ o5+40(FP), R13
	MOVQ o6+48(FP), R14
	MOVQ o7+56(FP), R15
	MOVQ va+64(FP), SI
	MOVQ vb+72(FP), DI
	MOVQ wa+80(FP), AX
	MOVQ wb+88(FP), BX
	VMOVSS 0(AX), X0
	VBROADCASTSS X0, Z16
	VMOVSS 4(AX), X0
	VBROADCASTSS X0, Z17
	VMOVSS 8(AX), X0
	VBROADCASTSS X0, Z18
	VMOVSS 12(AX), X0
	VBROADCASTSS X0, Z19
	VMOVSS 16(AX), X0
	VBROADCASTSS X0, Z20
	VMOVSS 20(AX), X0
	VBROADCASTSS X0, Z21
	VMOVSS 24(AX), X0
